protected override void OnModelCreating(ModelBuilder modelBuilder)
{
    modelBuilder.Entity<Product>(entity =>
    {
        entity.ToContainer("Products");

        // Preserve EF Core 8 discriminator property name so existing documents
        // (which store "Discriminator") remain readable. EF Core 9 defaults to "$type".
        entity.HasDiscriminator<string>("Discriminator");

        // Preserve EF Core 8 compound id format ("Product|123") so existing
        // documents remain accessible via FindAsync and point-reads.
        entity.HasRootDiscriminatorInJsonId(true);
    });
    // Removed HasIndex — Cosmos DB provider now throws at startup.
    // Manage indexing via the container's indexing policy in Azure Portal / Bicep.
}

